using System;using System.IO;using System.Diagnostics;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;
namespace TerrainFoundry{class LauncherLifecycleTests{
 [STAThread]static void Main(){Application.EnableVisualStyles();if(Path.GetFileName(Application.ExecutablePath)=="TerrainFoundry.exe"){var target=Environment.GetEnvironmentVariable("TERRAIN_ASSET_PACKS");if(String.IsNullOrEmpty(target))throw new Exception("Scenery environment missing");var child=new Form{Text="Isolated editor startup fixture"};child.Shown+=(s,e)=>File.WriteAllText(Environment.GetEnvironmentVariable("TERRAIN_UI_RECEIPT"),Process.GetCurrentProcess().Id+"\n"+target);Application.Run(child);return;}string root=Path.Combine(Path.GetTempPath(),"terrain-launcher-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("TERRAIN_TEST_ROOT",root);var flags=BindingFlags.Instance|BindingFlags.NonPublic;var method=typeof(Launcher).GetMethod("OpenVerifiedEditor",flags);int childPid=0;try{var form=(Form)Activator.CreateInstance(typeof(Launcher),true);form.Show();Application.DoEvents();var status=(Label)typeof(Launcher).GetField("status",flags).GetValue(form);if(status.Bounds.Bottom>form.ClientSize.Height)throw new Exception("Status clipped");typeof(Launcher).GetField("batchTotal",flags).SetValue(form,3000000000L);typeof(Launcher).GetField("batchComplete",flags).SetValue(form,1000000000L);typeof(Launcher).GetField("batchCurrent",flags).SetValue(form,500000000L);typeof(Launcher).GetField("batchCount",flags).SetValue(form,3);typeof(Launcher).GetField("batchDone",flags).SetValue(form,1);typeof(Launcher).GetMethod("Progress",flags).Invoke(form,new object[]{"Downloading fixture",50});if(!status.Text.Contains("Overall 50%")||!status.Text.Contains("1 of 3 packages ready")||!status.Text.Contains("1.50 GB"))throw new Exception("Overall download progress missing");typeof(Launcher).GetField("batchCurrent",flags).SetValue(form,2000000000L);typeof(Launcher).GetMethod("Progress",flags).Invoke(form,new object[]{"Verifying fixture",-1});if(!status.Text.Contains("Overall 99%"))throw new Exception("Unverified download reported complete");typeof(Launcher).GetField("batchTotal",flags).SetValue(form,0L);var play=(Button)typeof(Launcher).GetField("play",flags).GetValue(form);if(play.Right>form.ClientSize.Width||play.Bottom>play.Parent.ClientSize.Height)throw new Exception("Open Editor clipped");var fail=(Task)method.Invoke(form,new object[]{Path.Combine(root,"missing"),new Dictionary<string,object>()});try{fail.GetAwaiter().GetResult();throw new Exception("Missing editor accepted");}catch(System.ComponentModel.Win32Exception){}if(form.IsDisposed)throw new Exception("Failed launch closed launcher");string client=Path.Combine(root,"client");Directory.CreateDirectory(client);File.Copy(Application.ExecutablePath,Path.Combine(client,"TerrainFoundry.exe"));string receipt=Path.Combine(root,"child.txt");Environment.SetEnvironmentVariable("TERRAIN_UI_RECEIPT",receipt);var task=(Task)method.Invoke(form,new object[]{client,new Dictionary<string,object>{{"fixture",root}}});var timeout=DateTime.UtcNow.AddSeconds(15);while(!task.IsCompleted&&DateTime.UtcNow<timeout){Application.DoEvents();System.Threading.Thread.Sleep(10);}task.GetAwaiter().GetResult();if(!form.IsDisposed)throw new Exception("Successful launch left launcher open");timeout=DateTime.UtcNow.AddSeconds(5);while(!File.Exists(receipt)&&DateTime.UtcNow<timeout)System.Threading.Thread.Sleep(10);var lines=File.ReadAllLines(receipt);childPid=Int32.Parse(lines[0]);if(!lines[1].Contains("fixture"))throw new Exception("Scenery paths lost");Console.WriteLine("PASS launcher controls fit, failed startup remains open, successful editor startup closes launcher and passes scenery paths.");}finally{if(childPid!=0)using(var child=Process.GetProcessById(childPid)){if(child.MainModule.FileName==Path.Combine(root,"client","TerrainFoundry.exe")){child.Kill();child.WaitForExit(5000);}}Directory.Delete(root,true);}}}}
